    {
      "criterion": "reshape",
      "value": 1,
      "ref": "card:sequential_part",
      "reason": "Runs are independent copies batched across GPUs; method is none, so no step-after-step dependency is removed."
    },
    {
      "criterion": "baseline",
      "value": "NA",
      "ref": "card:method",
      "reason": "restructuring.method is none, so baseline criterion not applicable."
